-- =============================================================================
-- crm_finance — Datos de demostracion
-- -----------------------------------------------------------------------------
--   100 usuarios del sistema repartidos entre los 18 roles operativos
--     (9 de Banca y 9 de Seguros), con distintas categorias.
--   500 clientes con un contrato VIGENTE cada uno, mitad Banca mitad Seguros,'
--     asignados a esos usuarios (cada cliente al area de su ejecutivo).
--
-- NO se carga solo: no esta montado en /docker-entrypoint-initdb.d a proposito,
-- porque son datos de prueba. Se ejecuta a mano cuando se quiere poblar.
--
-- Los ids van en un rango alto (usuarios y clientes desde 1001) para no chocar
-- nunca con filas creadas desde la API. INSERT IGNORE lo hace reejecutable.
--
-- Generado con semilla fija: el fichero es reproducible byte a byte.
-- =============================================================================

SET NAMES utf8mb4;

USE `crm_finance`;

