-- Resumen
SELECT 'usuarios' AS que, COUNT(*) AS total FROM `users`
UNION ALL SELECT 'clientes', COUNT(*) FROM `clients`
UNION ALL SELECT '  personas fisicas', COUNT(*) FROM `phisic_person_client`
UNION ALL SELECT '  personas morales', COUNT(*) FROM `moral_person_client`
UNION ALL SELECT 'contratos vigentes', COUNT(*) FROM `products_contract` WHERE contract_status_id = 1
UNION ALL SELECT '  de Banca', COUNT(*) FROM `bank_contract`
UNION ALL SELECT '  de Seguros', COUNT(*) FROM `insurance_contranct`;
